// One source for purchase previews, upgrades and live combat calculations.
export const CASTLE_MAX_LEVEL=5;
export const CASTLE_TIERS=['Basic','Improved','Reinforced','Advanced','Elite'];
export function castleStats(base,b={}){const level=Math.max(1,Math.min(5,Math.round(b.level||1))),n=level-1;const material=b.material||'standard',mat={standard:[1,1,1],oak:[.8,.72,.6],iron:[1.25,1.55,1.8],crystal:[1.4,1.8,.8]}[material]||[1,1,1],troop=base.id==='footman',archer=base.id==='archer',weapon=['cannon','ballista','catapult','rune'].includes(base.id),repair=base.id==='repair',trap=base.id==='trap';let hp=base.hp*(troop?[1,1.25,1.55,1.9,2.3][n]:archer?[1,1.2,1.45,1.75,2.1][n]:weapon?1+n*.28:[1,1.45,2,2.65,3.4][n]);const damage=troop?[9,12,16,21,27][n]:archer?13+4*n:Math.round((base.damage||0)*(1+n*(trap?.25:.28))),period=troop?[900,870,820,760,700][n]:Math.round((base.period||0)*(1-n*(archer?.06:.045))),range=troop?47:(base.range||0)+(base.range?n*(archer?20:weapon?15:8):0),splash=base.id==='cannon'?42+n*5:base.id==='catapult'?75+n*8:0;const cost=Math.round(base.cost*mat[0]),investment=Array.from({length:n},(_,i)=>Math.ceil(cost*(.65+i*.38)/5)*5).reduce((s,c)=>s+c,0);return{...base,level,tier:CASTLE_TIERS[n],hp:Math.round(hp*mat[1]),cost,investment,weight:base.weight*mat[2],damage,period,range,splash,speed:troop?[62,64,66,69,72][n]:0,heal:repair?3+n:0,armor:troop||archer||weapon?0:n*.03,projectile:{archer:'Arrow',cannon:'Cannonball',ballista:'Bolt',catapult:'Stone',rune:'Frost'}[base.id],upgradeCost:level<5?Math.ceil(cost*(.65+n*.38)/5)*5:null};}
export function kingStats(level=1){const n=Math.max(0,Math.min(4,Math.round(level)-1));return{name:'The King',id:'king',level:n+1,tier:CASTLE_TIERS[n],hp:800,damage:[3,5,8,12,18][n],period:[1400,1350,1250,1150,1050][n],range:[240,260,280,300,320][n],projectile:'Royal star',speed:500+n*20,cost:0,investment:[0,110,290,570,990][n],upgradeCost:[110,180,280,420,null][n]};}
export function healthBarAlpha(item,clock){const age=clock-(item.hurtAt??-Infinity);return age<2500?1:Math.max(0,1-(age-2500)/500);}
